mapper.sql:
FROM instrument i
LEFT JOIN market_snapshot ms ON ms.instrument_id = i.instrument_id
WHERE i.instrument_type IN ('STOCK', 'ETF')

    AND (i.code LIKE '%' || #{keyword} || '%' OR i.name LIKE '%' || #{keyword} || '%')


    AND i.board = #{board}


    AND i.instrument_type = #{instrumentType}

mapper.select:
SELECT i.instrument_id, i.code, i.name, i.instrument_type, i.board, ms.last_price, ms.pct_chg, ms.volume, ms.amount, ms.turnover_rate, ms.pe_ttm, ms.pb, ms.total_mv, ms.circ_mv
ORDER BY
(${sortColumn} IS NULL) ASC, ${sortColumn} ${sortDirection}, i.instrument_id ASC LIMIT #{limit} OFFSET #{offset}
